  `gateway_transaction_ref` varchar(190) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `refunds_payment_id` bigint unsigned DEFAULT NULL,
  `idempotency_key` char(40) COLLATE utf8mb4_unicode_ci NOT NULL,
