  CONSTRAINT `products_meeting_point_id_foreign` FOREIGN KEY (`meeting_point_id`) REFERENCES `ports` (`id`) ON DELETE SET NULL,
  CONSTRAINT `products_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `products_vat_rate_id_foreign` FOREIGN KEY (`vat_rate_id`) REFERENCES `vat_rates` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `products_vessel_id_foreign` FOREIGN KEY (`vessel_id`) REFERENCES `vessels` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `quote_line_items`;
CREATE TABLE `quote_line_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `quote_id` bigint unsigned NOT NULL,
  `label` json NOT NULL,
  `description` json DEFAULT NULL,
  `kind` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'charter',
  `qty` smallint unsigned NOT NULL DEFAULT '1',
  `unit_price_cents` int unsigned NOT NULL DEFAULT '0',
  `total_cents` int unsigned NOT NULL DEFAULT '0',
  `sort_order` smallint unsigned NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `quote_line_items_quote_id_foreign` (`quote_id`),
  KEY `quote_lines_tenant_quote_sort_idx` (`tenant_id`,`quote_id`,`sort_order`),
  CONSTRAINT `quote_line_items_quote_id_foreign` FOREIGN KEY (`quote_id`) REFERENCES `quotes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `quote_line_items_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `quotes`;
CREATE TABLE `quotes` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` bigint unsigned NOT NULL,
  `booking_id` bigint unsigned NOT NULL,
  `version` smallint unsigned NOT NULL DEFAULT '1',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `quote_token` char(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `subtotal_cents` int unsigned NOT NULL DEFAULT '0',
  `discount_cents` int unsigned NOT NULL DEFAULT '0',
  `total_cents` int unsigned NOT NULL DEFAULT '0',
  `deposit_cents` int unsigned NOT NULL DEFAULT '0',
  `vat_rate_bp` smallint unsigned NOT NULL,
  `valid_until` timestamp NOT NULL,
  `message` text COLLATE utf8mb4_unicode_ci,
  `terms` text COLLATE utf8mb4_unicode_ci,
  `sent_at` timestamp NULL DEFAULT NULL,
  `viewed_at` timestamp NULL DEFAULT NULL,
  `accepted_at` timestamp NULL DEFAULT NULL,
  `declined_at` timestamp NULL DEFAULT NULL,
  `decline_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `expired_at` timestamp NULL DEFAULT NULL,
  `created_by_user_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `quotes_tenant_booking_version_uq` (`tenant_id`,`booking_id`,`version`),
  UNIQUE KEY `quotes_uuid_unique` (`uuid`),
  UNIQUE KEY `quotes_quote_token_unique` (`quote_token`),
  KEY `quotes_booking_id_foreign` (`booking_id`),
  KEY `quotes_created_by_user_id_foreign` (`created_by_user_id`),
  KEY `quotes_tenant_status_valid_idx` (`tenant_id`,`status`,`valid_until`),
  CONSTRAINT `quotes_booking_id_foreign` FOREIGN KEY (`booking_id`) REFERENCES `bookings` (`id`) ON DELETE CASCADE,
  CONSTRAINT `quotes_created_by_user_id_foreign` FOREIGN KEY (`created_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `quotes_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `rate_plan_prices`;
CREATE TABLE `rate_plan_prices` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `rate_plan_id` bigint unsigned NOT NULL,
  `age_band_id` bigint unsigned NOT NULL,
  `price_cents` int unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `rate_plan_prices_plan_band_uq` (`tenant_id`,`rate_plan_id`,`age_band_id`),
  KEY `rate_plan_prices_rate_plan_id_foreign` (`rate_plan_id`),
  KEY `rate_plan_prices_age_band_id_foreign` (`age_band_id`),
  KEY `rate_plan_prices_tenant_plan_idx` (`tenant_id`,`rate_plan_id`),
  CONSTRAINT `rate_plan_prices_age_band_id_foreign` FOREIGN KEY (`age_band_id`) REFERENCES `age_bands` (`id`) ON DELETE CASCADE,
  CONSTRAINT `rate_plan_prices_rate_plan_id_foreign` FOREIGN KEY (`rate_plan_id`) REFERENCES `rate_plans` (`id`) ON DELETE CASCADE,
  CONSTRAINT `rate_plan_prices_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `rate_plans`;
CREATE TABLE `rate_plans` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `product_id` bigint unsigned NOT NULL,
  `season_id` bigint unsigned DEFAULT NULL,
  `name` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vessel_price_cents` int unsigned DEFAULT NULL,
  `extra_hour_price_cents` int unsigned DEFAULT NULL,
  `included_pax` smallint unsigned DEFAULT NULL,
  `extra_pax_price_cents` int unsigned DEFAULT NULL,
  `deposit_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `deposit_percent` tinyint unsigned DEFAULT NULL,
  `deposit_fixed_cents` int unsigned DEFAULT NULL,
  `min_lead_time_hours` smallint unsigned NOT NULL DEFAULT '0',
  `max_advance_days` smallint unsigned DEFAULT NULL,
  `min_pax_override` smallint unsigned DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `balance_due_days_before_departure` smallint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `rate_plans_tenant_prod_season_uq` (`tenant_id`,`product_id`,`season_id`),
  KEY `rate_plans_product_id_foreign` (`product_id`),
  KEY `rate_plans_season_id_foreign` (`season_id`),
  KEY `rate_plans_tenant_product_idx` (`tenant_id`,`product_id`,`is_active`),
  CONSTRAINT `rate_plans_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE,
  CONSTRAINT `rate_plans_season_id_foreign` FOREIGN KEY (`season_id`) REFERENCES `seasons` (`id`) ON DELETE CASCADE,
  CONSTRAINT `rate_plans_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `role_assignments`;
CREATE TABLE `role_assignments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned NOT NULL,
  `role` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `granted_by_user_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `role_assign_tenant_user_role_uq` (`tenant_id`,`user_id`,`role`),
  KEY `role_assignments_user_id_foreign` (`user_id`),
  KEY `role_assignments_granted_by_user_id_foreign` (`granted_by_user_id`),
  KEY `role_assign_tenant_role_idx` (`tenant_id`,`role`),
  CONSTRAINT `role_assignments_granted_by_user_id_foreign` FOREIGN KEY (`granted_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `role_assignments_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `role_assignments_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `schedule_rules`;
CREATE TABLE `schedule_rules` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `product_id` bigint unsigned NOT NULL,
  `vessel_id` bigint unsigned DEFAULT NULL,
  `weekday_mask` tinyint unsigned NOT NULL,
  `start_time` time NOT NULL,
  `valid_from` date NOT NULL,
  `valid_until` date DEFAULT NULL,
  `capacity_override` smallint unsigned DEFAULT NULL,
  `generate_days_ahead` smallint unsigned NOT NULL DEFAULT '180',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `last_generated_on` date DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `schedule_rules_product_id_foreign` (`product_id`),
  KEY `schedule_rules_vessel_id_foreign` (`vessel_id`),
  KEY `schedule_rules_tenant_active_idx` (`tenant_id`,`is_active`,`valid_from`),
  KEY `schedule_rules_tenant_product_idx` (`tenant_id`,`product_id`),
  CONSTRAINT `schedule_rules_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE,
  CONSTRAINT `schedule_rules_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `schedule_rules_vessel_id_foreign` FOREIGN KEY (`vessel_id`) REFERENCES `vessels` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `season_date_ranges`;
CREATE TABLE `season_date_ranges` (
