  `valid_from` date NOT NULL,
  `valid_to` date DEFAULT NULL,
  `is_selectable` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
