DROP TABLE IF EXISTS `vessels`;
CREATE TABLE `vessels` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` bigint unsigned NOT NULL,
  `name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `registration_number` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `length_cm` smallint unsigned DEFAULT NULL,
  `capacity_max` smallint unsigned NOT NULL,
  `crew_count` tinyint unsigned NOT NULL DEFAULT '1',
  `captain_name` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `home_port_id` bigint unsigned DEFAULT NULL,
  `turnaround_buffer_minutes` smallint unsigned DEFAULT NULL,
  `max_wind_bft` tinyint unsigned DEFAULT NULL,
  `description` json DEFAULT NULL,
  `specs` json NOT NULL,
  `images` json NOT NULL,
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `sort_order` smallint unsigned NOT NULL DEFAULT '0',
  `search_index` text COLLATE utf8mb4_unicode_ci,
  `name_sort` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `vessels_tenant_name_unique` (`tenant_id`,`name`),
  UNIQUE KEY `vessels_uuid_unique` (`uuid`),
  KEY `vessels_home_port_id_foreign` (`home_port_id`),
  KEY `vessels_tenant_status_idx` (`tenant_id`,`status`,`sort_order`),
  KEY `vessels_tenant_home_port_idx` (`tenant_id`,`home_port_id`),
  KEY `vessels_tenant_name_sort_idx` (`tenant_id`,`name_sort`),
  CONSTRAINT `vessels_home_port_id_foreign` FOREIGN KEY (`home_port_id`) REFERENCES `ports` (`id`) ON DELETE SET NULL,
  CONSTRAINT `vessels_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `voucher_redemptions`;
CREATE TABLE `voucher_redemptions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `voucher_id` bigint unsigned NOT NULL,
  `booking_id` bigint unsigned NOT NULL,
  `amount_cents` int unsigned NOT NULL,
  `redeemed_at` timestamp NOT NULL,
  `reversed_at` timestamp NULL DEFAULT NULL,
  `reversed_amount_cents` int unsigned NOT NULL DEFAULT '0',
  `reason` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `voucher_redemptions_v_b_uq` (`tenant_id`,`voucher_id`,`booking_id`),
  KEY `voucher_redemptions_voucher_id_foreign` (`voucher_id`),
  KEY `voucher_redemptions_booking_id_foreign` (`booking_id`),
  KEY `voucher_redemptions_tenant_voucher_idx` (`tenant_id`,`voucher_id`),
  CONSTRAINT `voucher_redemptions_booking_id_foreign` FOREIGN KEY (`booking_id`) REFERENCES `bookings` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `voucher_redemptions_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `voucher_redemptions_voucher_id_foreign` FOREIGN KEY (`voucher_id`) REFERENCES `vouchers` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `vouchers`;
CREATE TABLE `vouchers` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` bigint unsigned NOT NULL,
  `code` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount_cents` int unsigned NOT NULL,
  `remaining_cents` int unsigned NOT NULL,
  `currency` char(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'EUR',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `issued_at` timestamp NOT NULL,
  `expires_at` timestamp NULL DEFAULT NULL,
  `issued_for_booking_id` bigint unsigned DEFAULT NULL,
  `reason` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'goodwill',
  `notes` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `issued_by_user_id` bigint unsigned DEFAULT NULL,
  `expiry_reminder_sent_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `vouchers_tenant_code_uq` (`tenant_id`,`code`),
  UNIQUE KEY `vouchers_uuid_unique` (`uuid`),
  KEY `vouchers_issued_by_user_id_foreign` (`issued_by_user_id`),
  KEY `vouchers_tenant_status_expires_idx` (`tenant_id`,`status`,`expires_at`),
  KEY `vouchers_issued_for_booking_idx` (`tenant_id`,`issued_for_booking_id`),
  CONSTRAINT `vouchers_issued_by_user_id_foreign` FOREIGN KEY (`issued_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `vouchers_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `webhook_deliveries`;
CREATE TABLE `webhook_deliveries` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint unsigned NOT NULL,
  `webhook_endpoint_id` bigint unsigned NOT NULL,
  `event` varchar(48) COLLATE utf8mb4_unicode_ci NOT NULL,
  `event_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `payload` json NOT NULL,
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `attempts` tinyint unsigned NOT NULL DEFAULT '0',
  `next_attempt_at` timestamp NULL DEFAULT NULL,
  `response_status` smallint unsigned DEFAULT NULL,
  `response_body` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `duration_ms` int unsigned DEFAULT NULL,
  `delivered_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `wh_deliveries_event_id_uq` (`webhook_endpoint_id`,`event_id`),
  KEY `wh_deliveries_endpoint_created_idx` (`tenant_id`,`webhook_endpoint_id`,`created_at`),
  KEY `wh_deliveries_retry_idx` (`status`,`next_attempt_at`),
  CONSTRAINT `webhook_deliveries_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `webhook_deliveries_webhook_endpoint_id_foreign` FOREIGN KEY (`webhook_endpoint_id`) REFERENCES `webhook_endpoints` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `webhook_endpoints`;
CREATE TABLE `webhook_endpoints` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` bigint unsigned NOT NULL,
  `name` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `signing_secret` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `events` json NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `consecutive_failures` smallint unsigned NOT NULL DEFAULT '0',
  `disabled_at` timestamp NULL DEFAULT NULL,
  `last_delivery_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `webhook_endpoints_uuid_unique` (`uuid`),
  KEY `wh_endpoints_tenant_active_idx` (`tenant_id`,`is_active`),
  CONSTRAINT `webhook_endpoints_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

